class ScoringManager {
public:
    class Trick {
    public:
        enum TYPE {
            TYPE_TRICK,
            TYPE_GAP
        };

        TYPE type;
        int index;
        int flags;
        float time;
        int numSpins;
        float mouthDist;
        float lipDist;
        int repetitions;

        Trick();
        ~Trick() {}
        Trick &operator=(const Trick &right);
    };
};

template<class T>
struct _List_node {
    _List_node *next;
    _List_node *previous;
    T data;
};

struct _List_iterator_base {
    void *node;

    _List_iterator_base() {}
    explicit _List_iterator_base(void *value) : node(value) {}
};

template<class T, class Ref = T &, class Ptr = T *>
class _List_iterator : public _List_iterator_base {
public:
    typedef _List_node<T> node_type;

    _List_iterator() {}
    _List_iterator(node_type *value) : _List_iterator_base(value) {}
};

template<class T1, class T2>
inline void construct(T1 *pointer, const T2 &value)
{
    new((void *)pointer) T1(value);
}

template<class T, class Allocator = my_allocator<T> >
class list {
public:
    typedef _List_iterator<T, T &, T *> iterator;
    typedef _List_node<T> node_type;
    typedef unsigned int size_type;

    node_type *sentinel;

private:
    node_type *create_node(
        const T &value,
        __my_default_alloc_template *pool)
    {
        const unsigned int bytes = (sizeof(node_type) + 7) & ~7;
        const unsigned int index = bytes / 8 - 1;
        __default_alloc_object *raw =
            pool->_S_free_list[index];
        void *memory;
        if (!raw)
            memory = allocator_refill(bytes);
        else
        {
            pool->_S_free_list[index] =
                raw->_M_free_list_link;
            memory = raw;
        }

        node_type *created = (node_type *)memory;
        T *data = &created->data;
        if (data)
            construct(data, value);
        return created;
    }

    iterator insert_one(
        iterator position,
        const T &value,
        __my_default_alloc_template *pool)
    {
        node_type *created = create_node(value, pool);
        created->next = (node_type *)position.node;
        created->previous =
            ((node_type *)position.node)->previous;
        ((node_type *)position.node)->previous->next = created;
        ((node_type *)position.node)->previous = created;
        return created;
    }

public:
    void insert(iterator position, size_type count, const T &value)
    {
        if (count == 0)
            return;

        __my_default_alloc_template *pool = &allocator_pool;
        do
        {
            insert_one(position, value, pool);
            --count;
        }
        while (count != 0);
    }
};

